Poids : <<PATIENT_AT_POIDS>> kg"},"internalId":"7998e9e1-276f-285c-6859-e5a0c4105f32","borderCss":"","id":"IDENTITE"},{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Taille :"},"internalId":"65d6c1b7-d6db-9c32-fbf3-c6d05e3c8de6","borderCss":"","alignementHorizontal":"quesHAlignRight","style":"background-color:#D9EAF7"},{"width":2,"type":"col","typeCol":"TEXTEAVANCEE","prop":{"valeur":"<<PATIENT_AT_TAILLE>>"},"internalId":"0951b53f-240f-a803-09b5-660851d44f11","borderCss":"","id":"TAILLE"}],"type":"row","internalId":"958abbb0-51ad-b864-ccbf-45b65b450b3e","borderCss":""},{"cols":[{"width":12,"type":"col","typeCol":"TEXTETITRE","prop":{"valeur":"2. Type d'exposition"},"internalId":"7c22e012-919b-5df8-20f0-4f134f8701e7","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#DDEFD8"}],"type":"row","internalId":"549da591-eb1b-86e2-4c93-66c48f2977eb","borderCss":""},{"cols":[{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Type de MRP :"},"internalId":"dbfc05cf-c8df-2a59-6c51-c45f60dafa31","borderCss":"","alignementHorizontal":"quesHAlignRight","style":"background-color:#DDEFD8"},{"width":5,"type":"col","typeCol":"INPUT-LISTE-COMBO","prop":{"canedit":true,"datasourceMode":"CLASSIC","datasource":[{"code":"1","libelle":"1","libelleCr":"1"}],"sqlSource":null},"internalId":"d4a1d129-5ab6-e4a6-8dc7-82d14a026c63","borderCss":"","id":"MN_TYPE_MRP"},{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Cures prévues :"},"internalId":"601a7df5-6e89-e0ad-eb13-295d050f3810","borderCss":"","alignementHorizontal":"quesHAlignRight","style":"background-color:#DDEFD8"},{"width":3,"type":"col","typeCol":"INPUT-LISTE-RADIO","prop":{"canedit":true,"datasourceMode":"CLASSIC","sqlSource":null,"datasource":[{"code":"1","libelle":"1","libelleCr":"1"}],"valeur":"1"},"internalId":"08307d57-e45f-5400-bf03-f44d52cfbb7b","borderCss":"","id":"MN_CURE_COUNT"}],"type":"row","internalId":"6de1c0a8-285e-ba01-837a-bc5113ec92a4","borderCss":""},{"cols":[{"width":12,"type":"col","typeCol":"TEXTETITRE","prop":{"valeur":"3. Dosimétrie à 1 mètre"},"internalId":"d6c9da0e-d4a8-656b-e453-a2cbe11c9cc6","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#FCE4D6"}],"type":"row","internalId":"b7e748bd-717e-1a0f-ff66-fe0ab4d10c4a","borderCss":"","visibilityConditions":[{"colId":"MN_TYPE_MRP","colValue":"!iode131_benin"}]},{"cols":[{"width":3,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Débit de dose retenu :"},"internalId":"de0d91c2-671a-baeb-775a-8516b625919b","borderCss":"","alignementHorizontal":"quesHAlignRight","style":"background-color:#FCE4D6"},{"width":2,"type":"col","typeCol":"INPUT-NUMERIQUE","prop":{"canedit":true,"nbdecimal":2},"internalId":"656787de-a5c1-e55e-be4b-5160d4f7412b","borderCss":"","id":"MN_DOSI-1-M"},{"width":1,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"µSv/h"},"internalId":"5f037694-78ad-f93a-4d1e-3b19275472c3","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#FCE4D6"}],"type":"row","internalId":"6a929624-ed02-84ab-256f-8a9bdc8c2998","borderCss":"","visibilityConditions":[{"colId":"MN_TYPE_MRP","colValue":"!iode131_benin"}]},{"cols":[{"width":12,"type":"col","typeCol":"TEXTETITRE","prop":{"valeur":"4. Paramètres Iode-131 bénin"},"internalId":"af77ad85-5328-c507-b4b6-a8dff8b5e7c1","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#F4D7E8"}],"type":"row","internalId":"f0e8dcee-5e0a-a368-1198-a2decb5f08e9","borderCss":"","visibilityConditions":[{"colId":"MN_TYPE_MRP","colValue":"%benin%"}],"extendVisibilityOnGroup":false},{"cols":[{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Taux courbe :"},"internalId":"861e77b1-546b-a45c-51e2-0f9eaf2f5910","borderCss":"","alignementHorizontal":"quesHAlignRight","style":"background-color:#F4D7E8"},{"width":3,"type":"col","typeCol":"INPUT-TEXTE","prop":{"canedit":false,"dataFromPastSettings":{"controlId":"COURBE_FIX","refControlId":"COURBE_FIX"}},"internalId":"f7f43baf-738b-3343-484c-ac7357962362","borderCss":"","id":"COURBE_FIX"},{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Taux H24 retenu :"},"internalId":"f792c307-a46c-c876-8917-37f525070c6c","borderCss":"","alignementHorizontal":"quesHAlignRight","style":"background-color:#F4D7E8"},{"width":2,"type":"col","typeCol":"INPUT-NUMERIQUE","prop":{"canedit":true,"nbdecimal":1},"internalId":"9bda9d47-faa8-7178-ace9-1eddcdb1675c","borderCss":"","id":"MN_TAUX_H24"},{"width":1,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"%"},"internalId":"40660e53-66c9-e8fe-dc76-b10f836c4423","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#F4D7E8"},{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":""},"internalId":"46420ffc-dcaf-e8b4-886a-cd48efc7ffd9","borderCss":"","style":"background-color:#F4D7E8"}],"type":"row","internalId":"5faf11e3-5133-5f32-fef9-60f33d2226be","borderCss":"","visibilityConditions":[{"colId":"MN_TYPE_MRP","colValue":"%benin%"}]},{"cols":[{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Activité :"},"internalId":"c2a4e9ae-fb47-d028-a481-e30f9403030e","borderCss":"","alignementHorizontal":"quesHAlignRight","style":"background-color:#F4D7E8"},{"width":2,"type":"col","typeCol":"INPUT-NUMERIQUE","prop":{"canedit":true,"nbdecimal":1},"internalId":"5f24e16b-877b-d636-811e-b8bc9002fe68","borderCss":"","id":"MN_ACTIVITE_MBQ"},{"width":1,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"MBq"},"internalId":"239d6caa-6a7f-d769-fedf-0cd156f83a24","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#F4D7E8"},{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Équivalent :"},"internalId":"a8a18bb3-4435-8a18-7487-be8751937536","borderCss":"","alignementHorizontal":"quesHAlignRight","style":"background-color:#F4D7E8"},{"width":2,"type":"col","typeCol":"INPUT-NUMERIQUE","prop":{"canedit":true,"nbdecimal":3},"internalId":"fbe6ff8c-570c-b7f4-effd-b9ef1d301e54","borderCss":"","id":"MN_ACTIVITE_MCI"},{"width":1,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"mCi"},"internalId":"f5fa4544-cb4f-3a39-8803-ec52c76cc67f","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#F4D7E8"},{"width":2,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":""},"internalId":"e605023b-48cb-dbee-7f63-f05d06343c32","borderCss":"","style":"background-color:#F4D7E8"}],"type":"row","internalId":"05ca994c-aabc-01d8-15bd-574951b2a2cc","borderCss":"","visibilityConditions":[{"colId":"MN_TYPE_MRP","colValue":"%benin%"}]},{"cols":[{"width":12,"type":"col","typeCol":"TEXTETITRE","prop":{"valeur":"5. Générer les consignes"},"internalId":"63ac455d-b21e-f308-0026-52c5ef9856f2","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#FF8B75"}],"type":"row","internalId":"59d350e3-d50d-85d9-b8fe-795a84911ecb","borderCss":""},{"cols":[{"width":4,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"Cliquez sur le bouton =>"},"internalId":"eb290567-72f8-f287-0622-4f161d20bc28","borderCss":"","style":"background-color:#FF8B75","alignementHorizontal":"quesHAlignRight","alignementVertical":"quesVAlignCenter"},{"width":4,"type":"col","typeCol":"BUTTON","prop":{"valeur":"Calculer les consignes avec RadIV","extendToColWidth":true},"internalId":"bd5bf1b2-a36d-0d31-28ef-8ef210b07338","borderCss":"","id":"MN_API_RADIV","style":"background-color:#C00000;color:#FFFFFF;font-weight:bold;font-size:14px"},{"width":4,"type":"col","typeCol":"TEXTESIMPLE","prop":{"valeur":"<= Cliquez sur le bouton"},"internalId":"64c090c1-12aa-ae5e-9b24-4a213877fd7a","borderCss":"","style":"background-color:#FF8B75","alignementHorizontal":"","alignementVertical":"quesVAlignCenter"}],"type":"row","internalId":"c5977780-b029-b773-84ab-e58205449294","borderCss":""},{"cols":[{"width":12,"type":"col","typeCol":"TEXTETITRE","prop":{"valeur":"6. Consignes générées"},"internalId":"f4a27a6e-1970-9594-6258-b3cc4f21c877","borderCss":"","alignementHorizontal":"quesHAlignLeft","style":"background-color:#E7E6F7"}],"type":"row","internalId":"679ad74b-083b-f9a0-1f2a-045ed16b6961","borderCss":""},{"cols":[{"width":12,"type":"col","typeCol":"INPUT-TEXTEAREA","prop":{"canedit":true,"height":650},"internalId":"46de6f02-31e8-7d7a-0bfa-fc98151af881","borderCss":"","id":"MN_CONSIGNES_RADIOPRO","style":"background-color:#E7E6F7"}],"type":"row","internalId":"361bd68d-7ff9-cd2c-c311-64194b85b822","borderCss":""}],"rattachement":"PROTOCOLE","javascript":"/*
CHAMPS REQUIS

TAILLE
 Type de champ attendu : Texte avancé avec balises
 Contenu attendu uniquement :
 <<PATIENT_AT_TAILLE>>
 Taille patient en m ou cm.
 Exemple :
 1.75 devient 175 cm
 175 reste 175 cm

MN_TYPE_MRP
 Type de champ attendu : Saisie combo simple
 Radiopharmaceutique sélectionné.
 Liste initialisée automatiquement depuis RadIV /api/config.

MN_CURE_COUNT
 Type de champ attendu : Saisie radio multiple
 Nombre de cures prévues.
 Liste initialisée automatiquement selon MN_TYPE_MRP.
 PSMA-177Lu : 1, 4 ou 6 cures
 Lutétium-177 NET : 1 ou 4 cures
 Autres isotopes : 1 cure

MN_CONSIGNES_RADIOPRO
 Champ résultat des consignes.

Pour tous les isotopes sauf iode131_benin :
MN_DOSI-1-M
 Débit de dose à 1 m en µSv/h.

Pour iode131_benin uniquement :
MN_ACTIVITE_MBQ
 Activité administrée en MBq.

MN_ACTIVITE_MCI
 Activité administrée en mCi.
 Conversion automatique avec MN_ACTIVITE_MBQ.

MN_TAUX_H24
 Taux de fixation en %.

Triggers :
LOAD
 Initialise MN_TYPE_MRP depuis RadIV /api/config
 Initialise MN_CURE_COUNT selon l’isotope sélectionné.

MN_TYPE_MRP
 Met à jour la liste MN_CURE_COUNT selon l’isotope sélectionné.

MN_API_RADIV
 Appelle RadIV et remplit MN_CONSIGNES_RADIOPRO.

MN_ACTIVITE_MBQ
 Convertit MBq vers mCi.

MN_ACTIVITE_MCI
 Convertit mCi vers MBq.
*/

switch (trigger) {
 case 'LOAD':
 initRadivIsotopeList();
 updateCureCountList();
 break;

 case 'MN_TYPE_MRP':
 updateCureCountList();
 break;

 case 'MN_API_RADIV':
 API();
 break;

 case 'MN_ACTIVITE_MBQ':
 convertBqCi("MBQ");
 break;

 case 'MN_ACTIVITE_MCI':
 convertBqCi("MCI");
 break;
}

function initRadivIsotopeList() {
 Tools.setListeDatasource("MN_TYPE_MRP", getFallbackRadivIsotopeDatasource());
 updateCureCountList();

 fetch("https://radiv.fr/api/config", {
 method: "GET",
 mode: "cors",
 cache: "no-store"
 })
 .then(function (response) {
 return response.text();
 })
 .then(function (text) {
 var responseData = parseJsonSafe(text);
 var configData = unwrapRadivResponse(responseData);
 var datasource = buildRadivDatasourceFromConfig(configData);

 if (datasource && datasource.length) {
 Tools.setListeDatasource("MN_TYPE_MRP", datasource);
 updateCureCountList();
 }
 })
 .catch(function () {
 Tools.setListeDatasource("MN_TYPE_MRP", getFallbackRadivIsotopeDatasource());
 updateCureCountList();
 });
}

function updateCureCountList() {
 var isotopeCode = getSelectedRadivCode();
 var datasource = [];

 if (isotopeCode === "psma_177lu") {
 datasource = [
 { id: 1, code: "1", libelle: "1 cure" },
 { id: 4, code: "4", libelle: "4 cures" },
 { id: 6, code: "6", libelle: "6 cures" }
 ];
 } else if (isotopeCode === "lutetium177_net") {
 datasource = [
 { id: 1, code: "1", libelle: "1 cure" },
 { id: 4, code: "4", libelle: "4 cures" }
 ];
 } else {
 datasource = [
 { id: 1, code: "1", libelle: "1 cure" }
 ];
 }

 Tools.setListeDatasource("MN_CURE_COUNT", datasource);

 var currentValue = Tools.getValue("MN_CURE_COUNT");

 if (currentValue && typeof currentValue === "object") {
 if (currentValue.id !== undefined && currentValue.id !== null) {
 currentValue = currentValue.id;
 } else if (currentValue.code !== undefined && currentValue.code !== null) {
 currentValue = currentValue.code;
 }
 }

 currentValue = toNumberOrNull(currentValue);

 var valid = false;

 for (var i = 0; i < datasource.length; i++) {
 if (Number(datasource[i].id) === Number(currentValue)) {
 valid = true;
 break;
 }
 }

 if (!valid) {
 Tools.setValue("MN_CURE_COUNT", datasource[0].id);
 }
}

function API() {
 var taille = normalizePatientSizeCm(toNumberOrNull(Tools.getValue("TAILLE")));
 var tauxFix = toNumberOrNull(Tools.getValue("MN_TAUX_H24"));
 var dosi1m = toNumberOrNull(Tools.getValue("MN_DOSI-1-M"));
 var isotopeCode = getSelectedRadivCode();

 if (!isotopeCode) {
 Tools.setValue("MN_CONSIGNES_RADIOPRO", "Erreur : aucun radiopharmaceutique sélectionné.");
 return;
 }

 if (!taille) {
 Tools.setValue("MN_CONSIGNES_RADIOPRO", "Erreur : la taille du patient est obligatoire.");
 return;
 }

 if (isotopeCode !== "iode131_benin" && !dosi1m) {
 Tools.setValue("MN_CONSIGNES_RADIOPRO", "Erreur : le débit de dose à 1 mètre est obligatoire.");
 return;
 }

 var payload = {
 calculation_mode: "sfmn",
 isotope_code: isotopeCode,
 dose_rate: dosi1m,
 patient_size_cm: taille,
 user_period_days: null,
 user_hours_1: null,
 user_distance_1: null,
 user_hours_2: null,
 user_limit: null,
 benign_activity_mbq: null,
 benign_fixation_pct: null,
 cure_count: getCureCount(isotopeCode)
 };

 if (isotopeCode === "iode131_benin") {
 var activiteMbq = toNumberOrNull(Tools.getValue("MN_ACTIVITE_MBQ"));

 payload.dose_rate = null;
 payload.patient_size_cm = taille;
 payload.benign_activity_mbq = activiteMbq;
 payload.benign_fixation_pct = tauxFix;

 if (!activiteMbq) {
 Tools.setValue("MN_CONSIGNES_RADIOPRO", "Erreur : l’activité en MBq est obligatoire pour Iode-131-Bénin.");
 return;
 }

 if (!tauxFix) {
 Tools.setValue("MN_CONSIGNES_RADIOPRO", "Erreur : le taux de fixation est obligatoire pour Iode-131-Bénin.");
 return;
 }
 }

 Tools.setValue("MN_CONSIGNES_RADIOPRO", "Calcul des consignes de radioprotection en cours...");

 callRadivWithFallback(payload)
 .then(function (result) {
 Tools.setValue("MN_CONSIGNES_RADIOPRO", result);
 })
 .catch(function (error) {
 Tools.setValue(
 "MN_CONSIGNES_RADIOPRO",
 "Erreur lors de l'appel à l'API RADIV : " + getErrorText(error)
 );
 });
}

function callRadivWithFallback(payload) {
 return callRadivCalculate(payload)
 .then(function (sfmnData) {
 var sfmnUnwrapped = unwrapRadivResponse(sfmnData);
 var sfmnRecommendations = extractRecommendationsDays(sfmnUnwrapped);

 if (sfmnUnwrapped && sfmnUnwrapped.ok !== false && sfmnRecommendations) {
 return genererTexteConsignesRadiv(sfmnUnwrapped, payload, false);
 }

 return retryLocalCalculation(payload, sfmnUnwrapped);
 })
 .catch(function (sfmnError) {
 return retryLocalCalculation(payload, {
 ok: false,
 error: {
 message: getErrorText(sfmnError)
 }
 });
 });
}

function retryLocalCalculation(originalPayload, sfmnErrorData) {
 var localPayload = cloneObject(originalPayload);
 localPayload.calculation_mode = "local";

 return callRadivCalculate(localPayload)
 .then(function (localData) {
 var localUnwrapped = unwrapRadivResponse(localData);

 if (!localUnwrapped || localUnwrapped.ok === false) {
 return (
 "Erreur : le calcul SFMN a échoué, puis le calcul local a également échoué.\n\n" +
 "Erreur SFMN :\n" +
 stringifySafe(sfmnErrorData) +
 "\n\nErreur locale :\n" +
 stringifySafe(localUnwrapped || localData)
 );
 }

 return genererTexteConsignesRadiv(localUnwrapped, localPayload, true);
 });
}

function callRadivCalculate(payload) {
 return fetch("https://radiv.fr/api/calculate", {
 method: "POST",
 mode: "cors",
 cache: "no-store",
 headers: {
 "Content-Type": "application/json"
 },
 body: JSON.stringify(payload)
 })
 .then(function (response) {
 return response.text().then(function (text) {
 var responseData = parseJsonSafe(text);

 if (!responseData) {
 return {
 ok: false,
 error: {
 message: "Réponse RADIV illisible",
 status: response.status,
 raw: text
 }
 };
 }

 var radivData = unwrapRadivResponse(responseData);

 if (!response.ok) {
 if (radivData && typeof radivData === "object") {
 radivData.ok = false;
 radivData.http_status = response.status;
 return radivData;
 }

 return {
 ok: false,
 error: {
 message: "Erreur HTTP RADIV",
 status: response.status,
 raw: text
 }
 };
 }

 return radivData;
 });
 });
}

function convertBqCi(source) {
 var mbq = toNumberOrNull(Tools.getValue("MN_ACTIVITE_MBQ"));
 var mci = toNumberOrNull(Tools.getValue("MN_ACTIVITE_MCI"));

 /*
 Conversion :
 1 mCi = 37 MBq
 MBq = mCi * 37
 mCi = MBq / 37
 */

 if (source === "MBQ") {
 if (mbq === null) {
 Tools.setValue("MN_ACTIVITE_MCI", null);
 return;
 }

 Tools.setValue("MN_ACTIVITE_MCI", roundNumber(mbq / 37, 3));
 return;
 }

 if (source === "MCI") {
 if (mci === null) {
 Tools.setValue("MN_ACTIVITE_MBQ", null);
 return;
 }

 Tools.setValue("MN_ACTIVITE_MBQ", roundNumber(mci * 37, 1));
 return;
 }
}

function unwrapRadivResponse(response) {
 if (!response) return null;

 if (typeof response === "string") {
 response = parseJsonSafe(response);
 if (!response) return null;
 }

 if (
 response.recommendations_days ||
 response.selected ||
 response.effective_hours !== undefined ||
 response.effective_days !== undefined ||
 response.radiopharmaceuticals ||
 response.isotopes
 ) {
 return response;
 }

 if (response.data) {
 if (typeof response.data === "string") {
 return unwrapRadivResponse(parseJsonSafe(response.data));
 }

 return unwrapRadivResponse(response.data);
 }

 if (response.result) {
 return unwrapRadivResponse(response.result);
 }

 if (response.body) {
 return unwrapRadivResponse(response.body);
 }

 return response;
}

function buildRadivDatasourceFromConfig(config) {
 if (!config) return [];

 var items =
 config.radiopharmaceuticals ||
 config.isotopes ||
 config.items ||
 config.data ||
 [];

 if (!items || !items.length) return [];

 var orderMap = {
 "iode131_benin": "01",
 "iode131_0_fixation": "02",
 "iode131_5_fixation": "03",
 "iode131_25_fixation": "04",
 "psma_177lu": "05",
 "lutetium177_net": "06",
 "radium223": "07",
 "mibg_131i": "08",
 "lipiodol_131i": "09",
 "microspheres_90y": "10",
 "microspheres_166ho": "11",
 "synovectomie_90y": "12",
 "synovectomie_186re": "13",
 "synovectomie_169er": "14"
 };

 var customLabels = {
 "iode131_benin": "Iode-131-Bénin",
 "iode131_0_fixation": "Iode-131-0%-fixation (cancer opéré)",
 "iode131_5_fixation": "Iode-131-5%-fixation (cancer oligométastatique)",
 "iode131_25_fixation": "Iode-131-25%-fixation (cancer métastatique)"
 };

 var datasource = [];

 for (var i = 0; i < items.length; i++) {
 var item = items[i];

 var apiCode =
 item.api_code ||
 item.isotope_code ||
 item.id ||
 item.code ||
 null;

 if (!apiCode) continue;
 if (apiCode === "non_defini") continue;

 var order = orderMap[apiCode] || String(90 + i);
 var label =
 customLabels[apiCode] ||
 item.label ||
 item.name ||
 item.libelle ||
 apiCode;

 datasource.push({
 id: apiCode,
 code: apiCode,
 libelle: order + " - " + label
 });
 }

 datasource.sort(function (a, b) {
 return String(a.libelle).localeCompare(String(b.libelle));
 });

 return datasource;
}

function getFallbackRadivIsotopeDatasource() {
 return [
 { id: "iode131_benin", code: "iode131_benin", libelle: "01 - Iode-131-Bénin" },
 { id: "iode131_0_fixation", code: "iode131_0_fixation", libelle: "02 - Iode-131-0%-fixation (cancer opéré)" },
 { id: "iode131_5_fixation", code: "iode131_5_fixation", libelle: "03 - Iode-131-5%-fixation (cancer oligométastatique)" },
 { id: "iode131_25_fixation", code: "iode131_25_fixation", libelle: "04 - Iode-131-25%-fixation (cancer métastatique)" },
