 { id: "synovectomie_169er", code: "synovectomie_169er", libelle: "14 - Synovectomie-169Er" }
 ];
}

function genererTexteConsignesRadiv(data, payload, usedFallbackLocal) {
 data = unwrapRadivResponse(data);

 var r = extractRecommendationsDays(data);
 var lignes = [];
 var isotopeCode = payload && payload.isotope_code ? payload.isotope_code : getSelectedRadivCode();

 ajouterConsigne(
 lignes,
 r,
 "conjoint_plus_60",
 "Si votre conjoint(e) a plus de 60 ans",
 "éviter les contacts très rapprochés et prolongés, privilégier une certaine distance et, si possible, dormir dans une chambre séparée",
 "si votre conjoint(e) a plus de 60 ans, vous n’avez aucune consigne d’éloignement particulière à respecter"
 );

 ajouterConsigne(
 lignes,
 r,
 "conjoint_moins_60",
 "Si votre conjoint(e) a moins de 60 ans",
 "limiter les contacts collés pendant de longues périodes et, si possible, dormir dans une chambre séparée",
 "si votre conjoint(e) a moins de 60 ans, vous n’avez aucune consigne d’éloignement particulière à respecter"
 );

 ajouterConsigne(
 lignes,
 r,
 "conjointe_enceinte",
 "Si votre conjointe est enceinte",
 "éviter les contacts rapprochés prolongés, ne pas dormir dans le même lit et garder une distance raisonnable la plupart du temps",
 "si votre conjointe est enceinte, vous n’avez aucune consigne d’éloignement particulière à respecter"
 );

 ajouterConsigne(
 lignes,
 r,
 "transport_commun",
 "Pour les trajets en transport en commun",
 "éviter les longs trajets en train, avion ou transport collectif en proximité prolongée ; si un déplacement long est indispensable, augmenter la distance dès que possible",
 "pour les trajets en transport en commun, vous n’avez aucune consigne d’éloignement particulière à respecter"
 );

 ajouterConsigne(
 lignes,
 r,
 "enfant_moins_3_ans",
 "Si vous êtes en contact avec un enfant de moins de 3 ans",
 "éviter de le garder longtemps sur vous, de le porter longtemps et toutes les situations où vous restez collés de facon prolongé ; si possible, confier les soins rapprochés prolongés à un autre adulte",
 "si vous êtes en contact avec un enfant de moins de 3 ans, vous n’avez aucune consigne d’éloignement particulière à respecter"
 );

 ajouterConsigne(
 lignes,
 r,
 "enfant_3_11_ans",
 "Si vous êtes en contact avec un enfant de 3 à 11 ans",
 "éviter les jeux très rapprochés, les longs câlins, le sommeil à côté de l’enfant et les moments serrés longtemps, par exemple un film collé sur le canapé ; garder une distance raisonnable la plupart du temps",
 "si vous êtes en contact avec un enfant de 3 à 11 ans, vous n’avez aucune consigne d’éloignement particulière à respecter"
 );

 ajouterConsigne(
 lignes,
 r,
 "collegues_travail",
 "Avec vos collègues de travail",
 "éviter le bureau côte à côte toute la journée, les réunions très longues en proximité et garder un peu d’espace avec vos collègues",
 "avec vos collègues de travail, vous n’avez aucune consigne d’éloignement particulière à respecter"
 );

 if (r && r.scenario_utilisateur !== null && r.scenario_utilisateur !== undefined) {
 ajouterConsigneScenarioUtilisateur(lignes, r.scenario_utilisateur);
 }

 var resume =
 getTitreCalcul(data, payload, usedFallbackLocal) + "\n" +
 getReferenceCalcul(data) +
 "Type d'exposition : " + getSelectedRadivLabel(data) + "\n";

 if (payload && Number(payload.cure_count) !== 1) {
 resume += "Calcul effectué pour " + payload.cure_count + " cures prévues.\n";
 }

 if (usedFallbackLocal === true) {
 resume += "Note : le mode SFMN a échoué ou n’a pas retourné de recommandations exploitables ; le calcul a donc été relancé automatiquement en mode local.\n";
 }

 if (isotopeCode === "iode131_benin") {
 resume +=
 "Activité administrée : " + formatNullable(payload.benign_activity_mbq) + " MBq\n" +
 "Soit : " + formatNullable(roundNumber(payload.benign_activity_mbq / 37, 3)) + " mCi\n" +
 "Taux de fixation : " + formatNullable(payload.benign_fixation_pct) + " %\n" +
 "Taille utilisée : " + formatNullable(payload.patient_size_cm) + " cm\n";
 } else {
 resume +=
 "Taille utilisée : " + formatNullable(payload.patient_size_cm) + " cm\n" +
 "Débit de dose utilisé : " + formatNullable(data.computed_dose_rate) + " µSv/h\n";
 }

 if (
 data.effective_hours !== null &&
 data.effective_hours !== undefined &&
 data.effective_days !== null &&
 data.effective_days !== undefined
 ) {
 resume +=
 "Période effective retenue : " +
 data.effective_hours +
 " heure(s), soit " +
 data.effective_days +
 " jour(s).\n";
 }

 resume += "\n";

 if (!r) {
 resume +=
 "Erreur : la réponse RADIV ne contient pas de recommandations exploitables.\n\n" +
 "Réponse utilisée par le script :\n" +
 stringifySafe(data);
 return resume;
 }

 if (!lignes.length) {
 resume +=
 "Erreur : les recommandations ont été trouvées, mais aucune clé attendue n’a été reconnue.\n\n" +
 "Recommandations reçues :\n" +
 stringifySafe(r);
 return resume;
 }

 return resume + lignes.join("\n\n");
}

function getTitreCalcul(data, payload, usedFallbackLocal) {
 data = unwrapRadivResponse(data);

 var mode =
 data.calculation_mode ||
 (payload && payload.calculation_mode) ||
 null;

 if (mode === "sfmn" && usedFallbackLocal !== true) {
 return "Consignes de radioprotection calculées sur l'application SFMN, interrogée par RadIV.FR.";
 }

 return "Consignes de radioprotection calculées avec RadIV.FR.";
}

function getReferenceCalcul(data) {
 data = unwrapRadivResponse(data);

 if (!data) {
 return "";
 }

 if (data.calculation_mode !== "local") {
 return "";
 }

 var reference = null;

 if (data.selected && data.selected.reference) {
 reference = data.selected.reference;
 }

 if (!reference && data.reference) {
 reference = data.reference;
 }

 if (!reference) {
 return "";
 }

 return "Référence : " + reference + "\n";
}

function extractRecommendationsDays(data) {
 data = unwrapRadivResponse(data);

 if (!data) return null;

 var direct = findRecommendationsDaysDeep(data);
 if (direct) return direct;

 var rows = findParsedRowsDeep(data);
 if (rows) return recommendationsFromParsedRows(rows);

 return null;
}

function findRecommendationsDaysDeep(obj) {
 if (!obj || typeof obj !== "object") return null;

 if (obj.recommendations_days && typeof obj.recommendations_days === "object") {
 return obj.recommendations_days;
 }

 for (var key in obj) {
 if (!obj.hasOwnProperty(key)) continue;

 var value = obj[key];

 if (value && typeof value === "object") {
 var found = findRecommendationsDaysDeep(value);
 if (found) return found;
 }
 }

 return null;
}

function findParsedRowsDeep(obj) {
 if (!obj || typeof obj !== "object") return null;

 if (obj.parsed_rows && obj.parsed_rows.length) {
 return obj.parsed_rows;
 }

 for (var key in obj) {
 if (!obj.hasOwnProperty(key)) continue;

 var value = obj[key];

 if (value && typeof value === "object") {
 var found = findParsedRowsDeep(value);
 if (found) return found;
 }
 }

 return null;
}

function recommendationsFromParsedRows(rows) {
 if (!rows || !rows.length) return null;

 var result = {
 conjoint_plus_60: null,
 conjoint_moins_60: null,
 conjointe_enceinte: null,
 transport_commun: null,
 enfant_moins_3_ans: null,
 enfant_3_11_ans: null,
 collegues_travail: null,
 scenario_utilisateur: null
 };

 for (var i = 0; i < rows.length; i++) {
 var row = rows[i];
 if (!row) continue;

 var code = row.audience_code || row.code || row.key || null;
 var label = row.label || "";
 var value = row.value;

 if (value === undefined || value === null) continue;

 if (code && result.hasOwnProperty(code)) {
 result[code] = value;
 continue;
 }

 label = String(label).toLowerCase();

 if (label.indexOf("> 60") !== -1 || label.indexOf("plus de 60") !== -1) {
 result.conjoint_plus_60 = value;
 } else if (label.indexOf("< 60") !== -1 || label.indexOf("moins de 60") !== -1) {
 result.conjoint_moins_60 = value;
 } else if (label.indexOf("enceinte") !== -1) {
 result.conjointe_enceinte = value;
 } else if (label.indexOf("transport") !== -1) {
 result.transport_commun = value;
 } else if (label.indexOf("<3") !== -1 || label.indexOf("moins de 3") !== -1) {
 result.enfant_moins_3_ans = value;
 } else if (label.indexOf("3 et 11") !== -1 || label.indexOf("entre 3") !== -1) {
 result.enfant_3_11_ans = value;
 } else if (label.indexOf("collègue") !== -1 || label.indexOf("collegue") !== -1 || label.indexOf("travail") !== -1) {
 result.collegues_travail = value;
 }
 }

 return result;
}

function ajouterConsigne(lignes, recommendations, key, debutPhrase, consignePositive, consigneZero) {
 if (!recommendations) return;

 var jours = recommendations[key];

 if (jours === null || jours === undefined) return;

 if (Number(jours) === 0) {
 lignes.push(capitalizeFirst(consigneZero) + ".");
 return;
 }

 lignes.push(
 debutPhrase +
 ", alors pendant " +
 jours +
 " jour" +
 (jours > 1 ? "s" : "") +
 ", il faut " +
 consignePositive +
 "."
 );
}

function ajouterConsigneScenarioUtilisateur(lignes, jours) {
 if (jours === null || jours === undefined) return;

 if (Number(jours) === 0) {
 lignes.push("Pour le scénario personnalisé, vous n’avez aucune consigne d’éloignement particulière à respecter.");
 return;
 }

 lignes.push(
 "Pour le scénario personnalisé, pendant " +
 jours +
 " jour" +
 (jours > 1 ? "s" : "") +
 ", il faut respecter les contraintes personnalisées définies pour ce scénario."
 );
}

function getSelectedRadivCode() {
 var selected = Tools.getValue("MN_TYPE_MRP");

 if (!selected) return null;

 if (typeof selected === "object") {
 if (selected.id) return normalizeRadivCode(selected.id);
 if (selected.code) return normalizeRadivCode(selected.code);
 }

 if (typeof selected === "string") {
 var fromDatasource = findRadivCodeFromDatasource(selected);
 return fromDatasource || normalizeRadivCode(selected);
 }

 return null;
}

function findRadivCodeFromDatasource(value) {
 var datasource = [];

 try {
 datasource = Tools.getListeDatasource("MN_TYPE_MRP") || [];
 } catch (e) {
 datasource = [];
 }

 for (var i = 0; i < datasource.length; i++) {
 if (datasource[i] && (datasource[i].id === value || datasource[i].code === value)) {
 return normalizeRadivCode(datasource[i].id);
 }
 }

 return null;
}

function normalizeRadivCode(value) {
 if (!value) return null;

 value = String(value);

 if (/^\d{2}-/.test(value)) {
 return value.substring(3);
 }

 return value;
}

function getCureCount(isotopeCode) {
 var value = Tools.getValue("MN_CURE_COUNT");

 if (value && typeof value === "object") {
 if (value.id !== undefined && value.id !== null) {
 value = value.id;
 } else if (value.code !== undefined && value.code !== null) {
 value = value.code;
 }
 }

 value = toNumberOrNull(value) || 1;

 if (isotopeCode === "psma_177lu") {
 return value === 1 || value === 4 || value === 6 ? value : 1;
 }

 if (isotopeCode === "lutetium177_net") {
 return value === 1 || value === 4 ? value : 1;
 }

 return 1;
}

function normalizePatientSizeCm(value) {
 if (value === null || value === undefined) return null;
 return value < 3 ? Math.round(value * 100) : Math.round(value);
}

function getSelectedRadivLabel(data) {
 data = unwrapRadivResponse(data);

 if (data && data.selected && data.selected.label) {
 return stripLeadingOrder(data.selected.label);
 }

 try {
 var libelle = Tools.getValueLibelleFromDatasource("MN_TYPE_MRP", " - ", true);
 if (libelle) return stripLeadingOrder(libelle);
 } catch (e) {}

 return getSelectedRadivCode() || "Non renseigné";
}

function stripLeadingOrder(label) {
 if (!label) return label;
 return String(label).replace(/^\d{2}\s*-\s*/, "");
}

function toNumberOrNull(value) {
 if (value === null || value === undefined || value === "") return null;

 if (typeof value === "string") {
 value = value.replace(",", ".");
 }

 var number = Number(value);
 return isNaN(number) ? null : number;
}

function parseJsonSafe(value) {
 try {
 if (typeof value === "object") return value;
 return JSON.parse(value);
 } catch (e1) {
 try {
 return Tools.jsonToObject(value);
 } catch (e2) {
 return null;
 }
 }
}

function formatNullable(value) {
 if (value === null || value === undefined) return "non renseigné";
 return String(value);
}

function getRadivErrorMessage(data, status) {
 data = unwrapRadivResponse(data);

 var message = "Erreur API RADIV.";

 if (status) message += "\nStatut HTTP : " + status;

 if (data && data.error) {
 if (data.error.message) message += "\nMessage : " + data.error.message;
 if (data.error.reason) message += "\nRaison : " + data.error.reason;
 if (data.error.code) message += "\nCode : " + data.error.code;
 }

 if (data && data.errors && data.errors.length) {
 message += "\nDétails : " + data.errors.join("\n");
 }

 return message;
}

function getErrorText(error) {
 if (!error) return "erreur inconnue";
 if (typeof error === "string") return error;
 if (error.message) return error.message;

 try {
 return JSON.stringify(error);
 } catch (e) {
 return String(error);
 }
}

function stringifySafe(value) {
 try {
 return JSON.stringify(value, null, 2);
 } catch (e) {
 return String(value);
 }
}

function cloneObject(obj) {
 return JSON.parse(JSON.stringify(obj));
}

function capitalizeFirst(text) {
 if (!text) return "";
 return text.charAt(0).toUpperCase() + text.slice(1);
}

function roundNumber(value, decimals) {
 var factor = Math.pow(10, decimals);
 return Math.round(value * factor) / factor;
