function findRecommendationsDaysDeep(obj) {
 if (!obj || typeof obj !== "object") return null;

 if (obj.recommendations_days && typeof obj.recommendations_days === "object") {
 return obj.recommendations_days;
 }

 for (var key in obj) {
 if (!obj.hasOwnProperty(key)) continue;

 var value = obj[key];

 if (value && typeof value === "object") {
 var found = findRecommendationsDaysDeep(value);
 if (found) return found;
 }
 }

 return null;
}

function findParsedRowsDeep(obj) {
 if (!obj || typeof obj !== "object") return null;

 if (obj.parsed_rows && obj.parsed_rows.length) {
 return obj.parsed_rows;
 }

 for (var key in obj) {
 if (!obj.hasOwnProperty(key)) continue;

 var value = obj[key];

 if (value && typeof value === "object") {
 var found = findParsedRowsDeep(value);
 if (found) return found;
 }
 }

 return null;
}

function recommendationsFromParsedRows(rows) {
 if (!rows || !rows.length) return null;

 var result = {
