 }

 label = String(label).toLowerCase();

 if (label.indexOf("> 60") !== -1 || label.indexOf("plus de 60") !== -1) {
 result.conjoint_plus_60 = value;
 } else if (label.indexOf("< 60") !== -1 || label.indexOf("moins de 60") !== -1) {
 result.conjoint_moins_60 = value;
 } else if (label.indexOf("enceinte") !== -1) {
 result.conjointe_enceinte = value;
 } else if (label.indexOf("transport") !== -1) {
 result.transport_commun = value;
 } else if (label.indexOf("<3") !== -1 || label.indexOf("moins de 3") !== -1) {
